import{u,c as a,j as t,a as r,G as l,k as p,e as h,al as i,B as d,o as n}from"./chunks/framework.ByhWQ_D0.js";const m={key:0},P=JSON.parse('{"title":"PX4-Autopilot v1.16.0 Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"ko/releases/1.16.md","filePath":"ko/releases/1.16.md"}'),f={name:"ko/releases/1.16.md"},X=Object.assign(f,{setup(c){const{site:s}=u();return(g,e)=>{const o=d("Badge");return n(),a("div",null,[e[10]||(e[10]=t("h1",{id:"px4-autopilot-v1-16-0-release-notes",tabindex:"-1"},[r("PX4-Autopilot v1.16.0 Release Notes "),t("a",{class:"header-anchor",href:"#px4-autopilot-v1-16-0-release-notes","aria-label":'Permalink to "PX4-Autopilot v1.16.0 Release Notes"'},"​")],-1)),l(o,{type:"info",text:"Candidate Release"}),p(s).title!=="PX4 Guide (main)"?(n(),a("div",m,e[0]||(e[0]=[t("div",{class:"custom-block danger"},[t("p",{class:"custom-block-title"},[r("This page is on a release branch, and hence possibly out of date. "),t("a",{href:"https://docs.px4.io/main/en/releases/main.html"},"See the latest version"),r(".")])],-1)]))):h("",!0),e[11]||(e[11]=i('<p>This document covers all changes in PX4 v1.16.0 since the previous stable release (<a href="./../releases/1.15.html">PX4 v1.15.0</a>).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>These notes include only changes merged in 2023 and later — commits before 2023 are not listed.</p></div><h2 id="read-before-upgrading" tabindex="-1">Read Before Upgrading <a class="header-anchor" href="#read-before-upgrading" aria-label="Permalink to &quot;Read Before Upgrading&quot;">​</a></h2><p>Please continue reading for <a href="#upgrade-guide">upgrade instructions</a>.</p><h2 id="major-changes" tabindex="-1">Major Changes <a class="header-anchor" href="#major-changes" aria-label="Permalink to &quot;Major Changes&quot;">​</a></h2><ul><li><strong>Rover support rework</strong><ul><li>New dedicated firmware build for rovers (airframe IDs 50000–52000)</li><li>Separate modules for Ackermann, differential and mecanum rovers, each with manual, acro, stabilized, position and auto modes</li><li>Shared pure-pursuit guidance library for all rover modules</li><li>Legacy rover position control module deprecated in favor of the new modules</li></ul></li></ul><h2 id="upgrade-guide" tabindex="-1">Upgrade Guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to &quot;Upgrade Guide&quot;">​</a></h2><ul><li><a href="https://github.com/PX4/PX4-Autopilot/pull/24648" target="_blank" rel="noreferrer">PX4-Autopilot#24648</a>: Added setting default for EKF2_EV_CTRL to 15 for VOXL 2 boards</li><li><a href="https://github.com/PX4/PX4-Autopilot/pull/22517" target="_blank" rel="noreferrer">PX4-Autopilot#22517</a>: Change default ethernet IP</li><li><a href="https://github.com/PX4/PX4-Autopilot/pull/24602" target="_blank" rel="noreferrer">PX4-Autopilot#24602</a>: remove serial port default from sf45 module</li></ul><h2 id="other-changes" tabindex="-1">Other changes <a class="header-anchor" href="#other-changes" aria-label="Permalink to &quot;Other changes&quot;">​</a></h2><h3 id="hardware-support" tabindex="-1">Hardware Support <a class="header-anchor" href="#hardware-support" aria-label="Permalink to &quot;Hardware Support&quot;">​</a></h3><ul><li><strong>[New Hardware]</strong> <a href="https://github.com/PX4/PX4-Autopilot/pull/23830" target="_blank" rel="noreferrer">PX4-Autopilot#23830</a>: Boards: ARK FPV FC</li><li><strong>[New Hardware]</strong> <a href="https://github.com/PX4/PX4-Autopilot/pull/23414" target="_blank" rel="noreferrer">PX4-Autopilot#23414</a>: board: add cuav 7-nano</li><li><strong>[New Hardware]</strong> <a href="https://github.com/PX4/PX4-Autopilot/pull/24769" target="_blank" rel="noreferrer">PX4-Autopilot#24769</a>: add new board corvon743v1</li><li><strong>[New Hardware]</strong> <a href="https://github.com/PX4/PX4-Autopilot/pull/24018" target="_blank" rel="noreferrer">PX4-Autopilot#24018</a>: boards: bluerobotics: navigator: Add initial support</li><li><strong>[New Hardware]</strong> <a href="https://github.com/PX4/PX4-Autopilot/pull/24147" target="_blank" rel="noreferrer">PX4-Autopilot#24147</a>: boards: add new board micoair743-v2</li><li><strong>[New Hardware]</strong> <a href="https://github.com/PX4/PX4-Autopilot/pull/23218" target="_blank" rel="noreferrer">PX4-Autopilot#23218</a>: boards: add new board micoair h743</li><li><strong>[New Hardware]</strong> <a href="https://github.com/PX4/PX4-Autopilot/pull/24512" target="_blank" rel="noreferrer">PX4-Autopilot#24512</a>: boards: Add FMUv6s target</li><li><strong>[New Hardware]</strong> <a href="https://github.com/PX4/PX4-Autopilot/pull/23927" target="_blank" rel="noreferrer">PX4-Autopilot#23927</a>: manifest: Add Skynode S baseboard</li><li><strong>[New Hardware]</strong> <a href="https://github.com/PX4/PX4-Autopilot/pull/23257" target="_blank" rel="noreferrer">PX4-Autopilot#23257</a>: Add Tropic VMU board support (Baseboard for Teensy 4.1)</li><li><strong>[New Hardware]</strong> <a href="https://github.com/PX4/PX4-Autopilot/pull/23697" target="_blank" rel="noreferrer">PX4-Autopilot#23697</a>: boards: add new board X-MAV AP-H743v2</li><li><strong>[New Hardware]</strong> <a href="https://github.com/PX4/PX4-Autopilot/pull/23551" target="_blank" rel="noreferrer">PX4-Autopilot#23551</a>: 3DR boards: Support for 3DR Control Zero H7 OEM Rev G</li><li><strong>[New Hardware]</strong> <a href="https://github.com/PX4/PX4-Autopilot/pull/23623" target="_blank" rel="noreferrer">PX4-Autopilot#23623</a>: new board support ZeroOne x6</li></ul><h3 id="공통" tabindex="-1">공통 <a class="header-anchor" href="#공통" aria-label="Permalink to &quot;공통&quot;">​</a></h3><ul><li><p><a href="./../sensor/optical_flow.html#scale-factor">Optical flow scaling factor - SENS_FLOW_SCALE</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/23936" target="_blank" rel="noreferrer">PX4-Autopilot#23936</a>).</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/22813" target="_blank" rel="noreferrer">PX4-Autopilot#22813</a>: Reintroduce optional parameter versioning mechanism for airframe maintainers</p></li><li><p><a href="./../config/battery.html">Battery level estimation improvements</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/23205" target="_blank" rel="noreferrer">PX4-Autopilot#23205</a>).</p><ul><li><a href="./../config/battery.html#voltage-based-estimation-with-load-compensation">Voltage-based estimation with load compensation</a> now uses a real-time estimate of the internal resistance of the battery to compensate voltage drops under load (with increased current), providing a better capacity estimate than with the raw measured voltage.</li><li>Thrust-based load compensation has been removed (along with the <code>BATn_V_LOAD_DROP</code> parameters, where <code>n</code> is the battery number).</li></ul></li><li><p>The <a href="./../config/safety.html#position-gnss-loss-failsafe">Position (GNSS) loss failsafe</a> configurable delay (<code>COM_POS_FS_DELAY</code>) has been removed. The failsafe will now trigger 1 second after position has been lost. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24063" target="_blank" rel="noreferrer">PX4-Autopilot#24063</a>).</p></li><li><p><a href="./../dev_log/log_encryption.html">Log Encryption</a> now generates an encrypted log that contains the public-key-encrypted symmetric key that can be used to decrypt it, instead of putting the key into a separate file. This makes log decryption much easier, as there is no need to download or identify a separate key file. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24024" target="_blank" rel="noreferrer">PX4-Autopilot#24024</a>).</p></li><li><p>The generic mission command timeout <a href="./../advanced_config/parameter_reference.html#MIS_COMMAND_TOUT">MIS_COMMAND_TOUT</a> parameter replaces the delivery-specific <code>MIS_PD_TO</code> parameter. Mission commands that may take some time to complete, such as those for controlling gimbals, winches, and grippers, will progress to the next item when either feedback is received or the timeout expires. This is often used to provide a minimum delay for hardware that does not provide completion feedback, so that it can reach the commanded state before the mission progresses. (<a href="https://github.com/PX4/PX4-Autopilot/pull/23960" target="_blank" rel="noreferrer">PX4-Autopilot#23960</a>).</p></li><li><p><strong>[uORB]</strong> Introduce a <a href="./../middleware/uorb.html#message-versioning">version field</a> for a subset of uORB messages (<a href="https://github.com/PX4/PX4-Autopilot/pull/23850" target="_blank" rel="noreferrer">PX4-Autopilot#23850</a>)</p></li><li><p><a href="./../config/compass.html">Compass calibration</a> disables internal compasses if an external compass is available. This typically reduces false warnings due to magnetometer inconsistencies. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24316" target="_blank" rel="noreferrer">PX4-Autopilot#24316</a>).</p></li></ul><h3 id="제어" tabindex="-1">제어 <a class="header-anchor" href="#제어" aria-label="Permalink to &quot;제어&quot;">​</a></h3><ul><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23863" target="_blank" rel="noreferrer">PX4-Autopilot#23863</a>: [Sponsored by ARK] Bidirectional DShot</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/24196" target="_blank" rel="noreferrer">PX4-Autopilot#24196</a>: Make control allocation and actuator effectiveness a non-module-specific library</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/24221" target="_blank" rel="noreferrer">PX4-Autopilot#24221</a>: Spacecraft Build and Bare Control Allocator</p></li><li><p>Configurable multicopter orbit-mode yaw via <code>MC_ORBIT_YAW_MOD</code> (<a href="https://github.com/PX4/PX4-Autopilot/pull/23358" target="_blank" rel="noreferrer">PX4-Autopilot#23358</a>)</p></li><li><p>Collision prevention now works in manual (acceleration-based) flight mode (<code>MPC_POS_MODE</code>) (<a href="https://github.com/PX4/PX4-Autopilot/pull/23507" target="_blank" rel="noreferrer">PX4-Autopilot#23507</a>)</p></li></ul><h3 id="estimation" tabindex="-1">Estimation <a class="header-anchor" href="#estimation" aria-label="Permalink to &quot;Estimation&quot;">​</a></h3><ul><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23854" target="_blank" rel="noreferrer">PX4-Autopilot#23854</a>: EKF2: ellipsoidal earth navigation</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23263" target="_blank" rel="noreferrer">PX4-Autopilot#23263</a>: EKF2: Terrain state</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23185" target="_blank" rel="noreferrer">PX4-Autopilot#23185</a>: ekf2: add mag type init</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23436" target="_blank" rel="noreferrer">PX4-Autopilot#23436</a>: ekf2: Optical flow enabled by default</p></li><li><p>Position-loss failsafe delay removed; triggers 1 s after loss (see Common)</p></li></ul><h3 id="센서" tabindex="-1">센서 <a class="header-anchor" href="#센서" aria-label="Permalink to &quot;센서&quot;">​</a></h3><ul><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23656" target="_blank" rel="noreferrer">PX4-Autopilot#23656</a>: Implemented AUAV absolute/differential pressure sensor support</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23639" target="_blank" rel="noreferrer">PX4-Autopilot#23639</a>: Implemented temperature sensor support for INA228 / INA238</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/22744" target="_blank" rel="noreferrer">PX4-Autopilot#22744</a>: Add Ublox ZED-F9P-15B</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/24316" target="_blank" rel="noreferrer">PX4-Autopilot#24316</a>: Mag cal: automatically disable internal mags if external ones are available</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23064" target="_blank" rel="noreferrer">PX4-Autopilot#23064</a>: BMP581: Add Bosch BMP581 barometer</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/22914" target="_blank" rel="noreferrer">PX4-Autopilot#22914</a>: Murata SCH16T IMU driver</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23023" target="_blank" rel="noreferrer">PX4-Autopilot#23023</a>: ST IIS2MDC Magnetometer driver</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/24121" target="_blank" rel="noreferrer">PX4-Autopilot#24121</a>: Include distance sensor in dds topics</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23925" target="_blank" rel="noreferrer">PX4-Autopilot#23925</a>: drivers: magnetometer: mmc5983ma: Add SPI support</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23909" target="_blank" rel="noreferrer">PX4-Autopilot#23909</a>: drivers/magnetometer/ak09916: Add support to AK09915</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23362" target="_blank" rel="noreferrer">PX4-Autopilot#23362</a>: Add Bosch BMM350 magnetometer</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/24316" target="_blank" rel="noreferrer">PX4-Autopilot#24316</a>: Compass calibration now disables internal compass when external unit present, reducing false warnings</p></li></ul><h3 id="시뮬레이션" tabindex="-1">시뮬레이션 <a class="header-anchor" href="#시뮬레이션" aria-label="Permalink to &quot;시뮬레이션&quot;">​</a></h3><ul><li><strong>SIH</strong>: <ul><li>The SIH on SITL <a href="./../sim_sih/#set-custom-takeoff-location">custom takeoff location</a> in now set using the normal unscaled GPS position values, where previously the value needed to be multiplied by 1E7. (<a href="https://github.com/PX4/PX4-Autopilot/pull/23363" target="_blank" rel="noreferrer">PX4-Autopilot#23363</a>).</li><li>SIH now supports the standard VTOL airframe (<a href="https://github.com/PX4/PX4-Autopilot/pull/24175" target="_blank" rel="noreferrer">PX4-Autopilot#24175</a>).</li></ul></li><li><strong>Gazebo</strong>: <ul><li>Gazebo Harmonic LTS release replaces Gazebo Garden as the version supported by PX4. The default installer scripts (used for CI) and documentation have been updated. This is required because Garden end-of-life is Nov 2024. (<a href="https://github.com/PX4/PX4-Autopilot/pull/23603" target="_blank" rel="noreferrer">PX4-Autopilot#23603</a>)</li><li>New vehicle model <code>x500_lidar_2d</code> — <a href="./../sim_gazebo_gz/vehicles.html#x500-quadrotor-with-2d-lidar">x500 Quadrotor with 2D Lidar</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/22418" target="_blank" rel="noreferrer">PX4-Autopilot#22418</a>, <a href="https://github.com/PX4/PX4-gazebo-models/pull/41" target="_blank" rel="noreferrer">PX4-gazebo-models#41</a>).</li><li>New vehicle model <code>x500_lidar_front</code> — <a href="./../sim_gazebo_gz/vehicles.html#x500-quadrotor-with-1d-lidar-front-facing">X500 Quadrotor with 1D LIDAR (Front-facing)</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/23879" target="_blank" rel="noreferrer">PX4-Autopilot#23879</a>, <a href="https://github.com/PX4/PX4-gazebo-models/pull/62/files" target="_blank" rel="noreferrer">PX4-gazebo-models#62</a>).</li><li>New vehicle model <code>x500_lidar_down</code> — <a href="./../sim_gazebo_gz/vehicles.html#x500-quadrotor-with-1d-lidar-down-facing">X500 Quadrotor with 1D LIDAR (Down-facing)</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/23879" target="_blank" rel="noreferrer">PX4-Autopilot#23879</a>, <a href="https://github.com/PX4/PX4-gazebo-models/pull/62/files" target="_blank" rel="noreferrer">PX4-gazebo-models#62</a>).</li><li>New vehicle model <code>r1_rover</code> — <a href="./../sim_gazebo_gz/vehicles.html#differential-rover">Aion Robotics R1 Rover</a> (<a href="https://github.com/PX4/PX4-Autopilot/pull/22402" target="_blank" rel="noreferrer">PX4-Autopilot#22402</a> and <a href="https://github.com/PX4/PX4-gazebo-models/pull/21" target="_blank" rel="noreferrer">PX4-gazebo-models#21</a>).</li><li>New vehicle model <code>rover_ackermann</code> — <a href="./../sim_gazebo_gz/vehicles.html#ackermann-rover">Ackermann Rover</a> (<a href="https://github.com/PX4/PX4-Autopilot/pull/23383" target="_blank" rel="noreferrer">PX4-Autopilot#23383</a> and <a href="https://github.com/PX4/PX4-gazebo-models/pull/46" target="_blank" rel="noreferrer">PX4-gazebo-models#46</a>).</li><li>New vehicle model <code>x500_gimbal</code> — <a href="./../sim_gazebo_gz/vehicles.html#x500-quadrotor-with-gimbal-front-facing">Quadrotor(x500) with gimbal (Front-facing) in Gazebo</a> (<a href="https://github.com/PX4/PX4-Autopilot/pull/23382" target="_blank" rel="noreferrer">PX4-Autopilot#23382</a> and <a href="https://github.com/PX4/PX4-gazebo-models/pull/47" target="_blank" rel="noreferrer">PX4-gazebo-models#47</a> and <a href="https://github.com/PX4/PX4-gazebo-models/pull/70" target="_blank" rel="noreferrer">PX4-gazebo-models#70</a>).</li><li>New vehicle model <code>quadtailsitter</code> — <a href="./../sim_gazebo_gz/vehicles.html#quad-tailsitter-vtol">Quad Tailsitter VTOL</a> (<a href="https://github.com/PX4/PX4-Autopilot/pull/23943" target="_blank" rel="noreferrer">PX4-Autopilot#23943</a> and <a href="https://github.com/PX4/PX4-gazebo-models/pull/65" target="_blank" rel="noreferrer">PX4-gazebo-models#65</a>).</li><li>New vehicle model <code>tiltrotor</code> — <a href="./../sim_gazebo_gz/vehicles.html#tiltrotor-vtol">Tiltrotor VTOL</a> (<a href="https://github.com/PX4/PX4-Autopilot/pull/24028" target="_blank" rel="noreferrer">PX4-Autopilot#24028</a> and <a href="https://github.com/PX4/PX4-gazebo-models/pull/66" target="_blank" rel="noreferrer">PX4-gazebo-models#66</a>).</li><li><a href="./../simulation/#simulation_speed">Faster than Real-time Simulation</a> (<a href="https://github.com/PX4/PX4-Autopilot/pull/24421" target="_blank" rel="noreferrer">PX4-Autopilot#24421</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/23783" target="_blank" rel="noreferrer">PX4-Autopilot#23783</a>)</li><li><a href="https://github.com/PX4/PX4-Autopilot/pull/24471" target="_blank" rel="noreferrer">PX4-Autopilot#24471</a>: Gazebo: Moving platform</li></ul></li></ul><h3 id="uxrce-dds-ros2" tabindex="-1">uXRCE-DDS / ROS2 <a class="header-anchor" href="#uxrce-dds-ros2" aria-label="Permalink to &quot;uXRCE-DDS / ROS2&quot;">​</a></h3>',22)),t("ul",null,[t("li",null,[e[1]||(e[1]=t("strong",null,"[Feature]",-1)),e[2]||(e[2]=r()),e[3]||(e[3]=t("a",{href:"https://github.com/PX4/PX4-Autopilot/pull/24113",target:"_blank",rel:"noreferrer"},"PX4-Autopilot#24113",-1)),e[4]||(e[4]=r(": ")),l(o,{type:"warning",text:"Experimental"}),e[5]||(e[5]=r()),e[6]||(e[6]=t("a",{href:"./../ros2/px4_ros2_msg_translation_node.html"},"ROS 2 Message Translation Node",-1)),e[7]||(e[7]=r(" to translate PX4 messages from one definition version to another dynamically"))]),e[8]||(e[8]=t("li",null,[t("a",{href:"https://github.com/PX4/PX4-Autopilot/pull/24582",target:"_blank",rel:"noreferrer"},"PX4-Autopilot#24582"),r(": dds_topics: add vtol_vehicle_status")],-1)),e[9]||(e[9]=t("li",null,[t("a",{href:"https://github.com/PX4/PX4-Autopilot/pull/24583",target:"_blank",rel:"noreferrer"},"PX4-Autopilot#24583"),r(": dds_topics: add home_position")],-1))]),e[12]||(e[12]=i('<h3 id="mavlink" tabindex="-1">MAVLink <a class="header-anchor" href="#mavlink" aria-label="Permalink to &quot;MAVLink&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="multi-rotor" tabindex="-1">Multi-Rotor <a class="header-anchor" href="#multi-rotor" aria-label="Permalink to &quot;Multi-Rotor&quot;">​</a></h3><ul><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/24173" target="_blank" rel="noreferrer">PX4-Autopilot#24173</a>: [Multirotor] add yaw torque low pass filter</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23943" target="_blank" rel="noreferrer">PX4-Autopilot#23943</a>: Add gz model for quadtailsitter</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23358" target="_blank" rel="noreferrer">PX4-Autopilot#23358</a>: Allow system-default <a href="./../flight_modes_mc/orbit.html">multicopter orbit mode</a> yaw behaviour to be configured, using the parameter <a href="./../advanced_config/parameter_reference.html#MC_ORBIT_YAW_MOD">MC_ORBIT_YAW_MOD</a></p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23507" target="_blank" rel="noreferrer">PX4-Autopilot#23507</a>: Adapted the <a href="./../computer_vision/collision_prevention.html">Collision Prevention</a> implementation to work in the default manual flight mode (Acceleration Based) <a href="./../advanced_config/parameter_reference.html#MPC_POS_MODE">MPC_POS_MODE</a>.</p></li></ul><h3 id="수직이착륙기-vtol" tabindex="-1">수직이착륙기(VTOL) <a class="header-anchor" href="#수직이착륙기-vtol" aria-label="Permalink to &quot;수직이착륙기(VTOL)&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="fixed-wing" tabindex="-1">Fixed-wing <a class="header-anchor" href="#fixed-wing" aria-label="Permalink to &quot;Fixed-wing&quot;">​</a></h3><ul><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/24167" target="_blank" rel="noreferrer">PX4-Autopilot#24167</a>: Fixedwing: fix wheel controller</p></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/pull/23520" target="_blank" rel="noreferrer">PX4-Autopilot#23520</a>: FixedWing: allow position control without valid global position</p></li><li><p>Improvement: Fixed-wing auto takeoff: enable setting takeoff flaps for hand/catapult launch. <a href="https://github.com/PX4/PX4-Autopilot/pull/23460" target="_blank" rel="noreferrer">PX4-Autopilot#23460</a></p></li></ul><h3 id="탐사선" tabindex="-1">탐사선 <a class="header-anchor" href="#탐사선" aria-label="Permalink to &quot;탐사선&quot;">​</a></h3><p>This release contains a major rework for the rover support in PX4:</p><ul><li>Complete restructure of the <a href="./../frames_rover/">rover related documentation</a>.</li><li>New firmware build specifically for <a href="./../config_rover/#flashing-the-rover-build">rovers</a>.</li><li>New module dedicated to <a href="./../frames_rover/#ackermann">Ackermann rovers</a>: <ul><li>The module currently supports <a href="./../flight_modes_rover/manual.html#manual-mode">manual mode</a>, <a href="./../flight_modes_rover/manual.html#acro-mode">acro mode</a>, <a href="./../flight_modes_rover/manual.html#stabilized-mode">stabilized mode</a>, <a href="./../flight_modes_rover/manual.html#position-mode">position mode</a> and <a href="./../flight_modes_rover/auto.html">auto modes</a>.</li></ul></li><li>New module dedicated to <a href="./../frames_rover/#differential">differential rovers</a>: <ul><li>The module currently supports <a href="./../flight_modes_rover/manual.html#manual-mode">manual mode</a>, <a href="./../flight_modes_rover/manual.html#acro-mode">acro mode</a>, <a href="./../flight_modes_rover/manual.html#stabilized-mode">stabilized mode</a>, <a href="./../flight_modes_rover/manual.html#position-mode">position mode</a> and <a href="./../flight_modes_rover/auto.html">auto modes</a>.</li></ul></li><li>New module dedicated to <a href="./../frames_rover/#mecanum">mecanum rovers</a>: <ul><li>The module currently supports <a href="./../flight_modes_rover/manual.html#manual-mode">manual mode</a>, <a href="./../flight_modes_rover/manual.html#acro-mode">acro mode</a>, <a href="./../flight_modes_rover/manual.html#stabilized-mode">stabilized mode</a>, <a href="./../flight_modes_rover/manual.html#position-mode">position mode</a> and <a href="./../flight_modes_rover/auto.html">auto modes</a>.</li></ul></li><li>Added rover-specific firmware build (<code>50000–52000</code>) for Ackermann, differential and mecanum rovers</li><li>Restructure of the <a href="./../airframes/airframe_reference.html#rover">rover airframe</a> numbering convention (<a href="https://github.com/PX4/PX4-Autopilot/pull/23506" target="_blank" rel="noreferrer">PX4-Autopilot#23506</a>). This also introduces several <a href="./../airframes/airframe_reference.html#rover">new rover airframes</a>: <ul><li>Generic Differential Rover <code>50000</code>.</li><li>Generic Ackermann Rover <code>51000</code>.</li><li>Axial SCX10 2 Trail Honcho <code>51001</code>.</li><li>Generic Mecanum Rover <code>52000</code>.</li></ul></li><li>Library for the <a href="./../config_rover/position_tuning.html#pure-pursuit-guidance-logic-info-only">pure pursuit guidance algorithm</a> that is shared by all the rover modules.</li><li><a href="./../frames_rover/#simulation">Simulation</a> for differential-steering and Ackermann rovers in gazebo (for release notes see <code>r1_rover</code> and <code>rover_ackermann</code> in <a href="#simulation">simulation</a>).</li><li>Deprecation of the <code>rover position control</code> module: Note that the legacy rover module still exists but has been superseded by the new dedicated modules.</li></ul><h3 id="infrastructure" tabindex="-1">Infrastructure <a class="header-anchor" href="#infrastructure" aria-label="Permalink to &quot;Infrastructure&quot;">​</a></h3><ul><li><a href="https://github.com/PX4/PX4-Autopilot/pull/24011" target="_blank" rel="noreferrer">PX4-Autopilot#24011</a>: standard_modes: add vehicle-type specific standard modes</li><li><a href="https://github.com/PX4/PX4-Autopilot/pull/24020" target="_blank" rel="noreferrer">PX4-Autopilot#24020</a>: ci: build all upload to releases</li><li><a href="https://github.com/PX4/PX4-Autopilot/pull/24002" target="_blank" rel="noreferrer">PX4-Autopilot#24002</a>: ci: px4-dev container</li><li><a href="https://github.com/PX4/PX4-Autopilot/pull/23937" target="_blank" rel="noreferrer">PX4-Autopilot#23937</a>: ci: workflow for ubuntu 24</li><li><a href="https://github.com/PX4/PX4-Autopilot/pull/23869" target="_blank" rel="noreferrer">PX4-Autopilot#23869</a>: ci: add test for Ubuntu 22.04</li><li><a href="https://github.com/PX4/PX4-Autopilot/pull/23574" target="_blank" rel="noreferrer">PX4-Autopilot#23574</a>: ci: try runs-on Dronecode Infra</li><li><a href="https://github.com/PX4/PX4-Autopilot/pull/23550" target="_blank" rel="noreferrer">PX4-Autopilot#23550</a>: ci: replace build workflows</li></ul>',13))])}}});export{P as __pageData,X as default};
